import {audioPreferences} from './impact-feedback.mjs';
export const ACTIONS=[['forward','Avancer'],['back','Reculer'],['left','Gauche'],['right','Droite'],['up','Monter / sauter'],['down','Descendre / accroupir'],['boost','Accélérer'],['interact','Interagir'],['light','Lampe'],['inventory','Inventaire MJ'],['recipe','Réglages MJ'],['rotate','Rotation MJ'],['select','Sélection MJ']];
const defaults={forward:['KeyW','KeyZ','ArrowUp'],back:['KeyS','ArrowDown'],left:['KeyA','KeyQ','ArrowLeft'],right:['KeyD','ArrowRight'],up:['Space'],down:['ShiftLeft','ShiftRight'],boost:['ControlLeft','ControlRight'],interact:['KeyF'],light:['KeyL'],inventory:['KeyE','KeyI'],recipe:['KeyR'],rotate:['KeyT'],select:['KeyV']};
const valid=c=>typeof c==='string'&&/^(Key[A-Z]|Arrow(Up|Down|Left|Right)|Space|Shift(Left|Right)|Control(Left|Right))$/.test(c);
export function bindingError(bindings,id,code){if(!Object.hasOwn(defaults,id)||!valid(code))return 'Touche réservée ou non prise en charge';for(const [k,label]of ACTIONS)if(k!==id&&(bindings[k]===code||defaults[k].includes(code)))return 'Touche réservée : '+label;return ''}
export function normalizeSettings(v={}){const c=v?.controls||{},bindings={};for(const [id]of ACTIONS){const key=c.bindings?.[id];if(valid(key)&&!bindingError(bindings,id,key))bindings[id]=key}return {audio:audioPreferences(v?.audio),controls:{layout:['auto','azerty','qwerty'].includes(c.layout)?c.layout:'auto',sensitivity:Number.isFinite(c.sensitivity)?Math.max(.25,Math.min(3,c.sensitivity)):1,invertY:c.invertY===true,bindings},video:{resolution:['auto','0.75','1','1.5'].includes(v?.video?.resolution)?v.video.resolution:'auto',effects:['auto','low','balanced','high'].includes(v?.video?.effects)?v.video.effects:'auto',fps:v?.video?.fps!==false}}}
export function createSettingsStore(storage){let raw={};try{raw=JSON.parse(storage.getItem('brumes-settings-v1')||'null')||{audio:JSON.parse(storage.getItem('brumes-audio-feedback-v1')||'{}'),controls:{layout:storage.getItem('brumes-keyboard')||'auto'}}}catch{}let state=normalizeSettings(raw);function set(section,patch){state=normalizeSettings({...state,[section]:{...state[section],...patch}});try{storage.setItem('brumes-settings-v1',JSON.stringify(state))}catch{}return state}return {get:()=>state,set,bind(id,code){const error=bindingError(state.controls.bindings,id,code);if(!error)set('controls',{bindings:{...state.controls.bindings,[id]:code}});return error}}}
export function controlAction(e,c){const key=String(e.key||'').toLowerCase(),code=e.code||'',custom=c.bindings;for(const [id,k]of Object.entries(custom))if(k===code)return id;let id={arrowup:'forward',arrowdown:'back',arrowleft:'left',arrowright:'right',' ':'up',shift:'down',control:'boost',f:'interact',l:'light',e:'inventory',i:'inventory',r:'recipe',t:'rotate',v:'select'}[key];if(!id)id=c.layout==='auto'&&code?{KeyW:'forward',KeyS:'back',KeyA:'left',KeyD:'right'}[code]:(c.layout==='azerty'?{z:'forward',s:'back',q:'left',d:'right'}:{w:'forward',s:'back',a:'left',d:'right'})[key];return id&&!custom[id]?id:null}
export function controlLabel(id,c){return c.bindings[id]|| (id==='forward'?(c.layout==='azerty'?'Z / ↑':'W / ↑'):id==='left'?(c.layout==='azerty'?'Q / ←':'A / ←'):defaults[id].map(k=>k.replace('Key','')).join(' / '))}
